36	   * \param mu2 is the square of the scale mu
37	   * \param m are the squares of the masses of the internal lines
38	   * \param p are the four-momentum suqared of the external lines
39	   */
40	  template<typename TOutput, typename TMass, typename TScale>
41	  void QCDLoop<TOutput,TMass,TScale>::integral(vector<TOutput> &res,
42	                                               TScale const& mu2,
43	                                               vector<TMass> const& m,
44	                                               vector<TScale> const& p) const
45	  {
46	    Topology<TOutput,TMass,TScale> *topos = nullptr;
47	    if (m.size() == 1 && p.size() == 0) topos = _tp;
48	    else if (m.size() == 2 && p.size() == 1) topos = _bb;
49	    else if (m.size() == 3 && p.size() == 3) topos = _tr;
50	    else if (m.size() == 4 && p.size() == 6) topos = _tb;
51	    else
52	      throw RangeError("QCDLoop","error topology not recognised");
53	
54	    topos->integral(res, mu2, m, p);
55	
56	    return;
57	  }
