// C++ declarations for the QCDLoop library C/Fortran interface.
// Translated from mod_qcdloop_c.f (Fortran module with bind(C) interfaces).

#ifndef MOD_QCDLOOP_C_HPP
#define MOD_QCDLOOP_C_HPP

#include <complex>

// Quad-precision types (GCC extension, matches QCDLoop qdouble/qcomplex).
// These are only usable when compiled with GCC; see original Fortran comment.
typedef __float128    ql_qdouble;
typedef __complex128  ql_qcomplex;

extern "C" {

  // Cache size control
  void qlcachesize(int const& csize);

  // Auxiliary utilities
  std::complex<double> cln(std::complex<double> const& x, double const& isig);
  bool qlzero(double const& x);
  bool qlnonzero(double const& x);

  // One-point (tadpole)
  std::complex<double> qli1(double const& m1, double const& mu2, int const& ep);
  std::complex<double> qli1c(std::complex<double> const& m1, double const& mu2, int const& ep);

  // Two-point (bubble)
  std::complex<double> qli2(double const& p1, double const& m1, double const& m2,
                             double const& mu2, int const& ep);
  std::complex<double> qli2c(double const& p1, std::complex<double> const& m1,
                              std::complex<double> const& m2, double const& mu2, int const& ep);

  // Two-point derivative
  std::complex<double> qli2p(double const& p1, double const& m1, double const& m2,
                              double const& mu2, int const& ep);
  std::complex<double> qli2pc(double const& p1, std::complex<double> const& m1,
                               std::complex<double> const& m2, double const& mu2, int const& ep);

  // Three-point (triangle)
  std::complex<double> qli3(double const& p1, double const& p2, double const& p3,
                             double const& m1, double const& m2, double const& m3,
                             double const& mu2, int const& ep);
  std::complex<double> qli3c(double const& p1, double const& p2, double const& p3,
                              std::complex<double> const& m1, std::complex<double> const& m2,
                              std::complex<double> const& m3, double const& mu2, int const& ep);

  // Four-point (box)
  std::complex<double> qli4(double const& p1, double const& p2, double const& p3, double const& p4,
                             double const& s12, double const& s23,
                             double const& m1, double const& m2, double const& m3, double const& m4,
                             double const& mu2, int const& ep);
  std::complex<double> qli4c(double const& p1, double const& p2, double const& p3, double const& p4,
                              double const& s12, double const& s23,
                              std::complex<double> const& m1, std::complex<double> const& m2,
                              std::complex<double> const& m3, std::complex<double> const& m4,
                              double const& mu2, int const& ep);

  // Quad-precision variants (GCC/gfortran only; no standard C binding for real128).
  ql_qcomplex qli1q(ql_qdouble const& m1, ql_qdouble const& mu2, int const& ep);
  ql_qcomplex qli2q(ql_qdouble const& p1, ql_qdouble const& m1, ql_qdouble const& m2,
                    ql_qdouble const& mu2, int const& ep);
  ql_qcomplex qli3q(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3,
                    ql_qdouble const& m1, ql_qdouble const& m2, ql_qdouble const& m3,
                    ql_qdouble const& mu2, int const& ep);
  ql_qcomplex qli4q(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3, ql_qdouble const& p4,
                    ql_qdouble const& s12, ql_qdouble const& s23,
                    ql_qdouble const& m1, ql_qdouble const& m2, ql_qdouble const& m3, ql_qdouble const& m4,
                    ql_qdouble const& mu2, int const& ep);

  ql_qcomplex qli1qc(ql_qcomplex const& m1, ql_qdouble const& mu2, int const& ep);
  ql_qcomplex qli2qc(ql_qdouble const& p1, ql_qcomplex const& m1, ql_qcomplex const& m2,
                     ql_qdouble const& mu2, int const& ep);
  ql_qcomplex qli3qc(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3,
                     ql_qcomplex const& m1, ql_qcomplex const& m2, ql_qcomplex const& m3,
                     ql_qdouble const& mu2, int const& ep);
  ql_qcomplex qli4qc(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3, ql_qdouble const& p4,
                     ql_qdouble const& s12, ql_qdouble const& s23,
                     ql_qcomplex const& m1, ql_qcomplex const& m2, ql_qcomplex const& m3, ql_qcomplex const& m4,
                     ql_qdouble const& mu2, int const& ep);

} // extern "C"

